import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { analyze, Architecture } from './analyze.js';

// Disk side of the architecture graph: reads the backend source and writes
// architecture.generated.ts, which the /api/admin/architecture endpoint
// serves. Run after changing routes/controllers/services/schema:
//   npm run arch:gen
// A test (architecture.test.ts) fails if the generated file is out of date,
// so a stale graph can't reach the `test` branch unnoticed.

const SRC = resolve(process.cwd(), 'src');
export const GENERATED_PATH = join(SRC, 'architecture', 'architecture.generated.ts');

export function readSourceFiles(): Record<string, string> {
  const files: Record<string, string> = {};
  for (const dir of ['routes', 'controllers', 'services']) {
    for (const f of readdirSync(join(SRC, dir))) {
      if (f.endsWith('.ts')) files[`${dir}/${f}`] = readFileSync(join(SRC, dir, f), 'utf8');
    }
  }
  files['db/schema.ts'] = readFileSync(join(SRC, 'db', 'schema.ts'), 'utf8');
  return files;
}

export function renderGenerated(arch: Architecture): string {
  return [
    '// AUTO-GENERATED by `npm run arch:gen` from the backend source — do not edit.',
    '// Powers Admin → Backend Architecture (GET /api/admin/architecture).',
    "import type { Architecture } from './analyze.js';",
    '',
    `export const ARCHITECTURE: Architecture = ${JSON.stringify(arch, null, 2)};`,
    '',
  ].join('\n');
}

export function buildFromDisk(): string {
  return renderGenerated(analyze(readSourceFiles()));
}

export function writeGenerated(): void {
  writeFileSync(GENERATED_PATH, buildFromDisk());
}
